import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Plan — FR 3.7.19: Recommend Collaborator (UC-106)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-19-recommend-collaborator/plan.md","filePath":"feature/srs/06-ai-features/3-7-19-recommend-collaborator/plan.md"}'),c={name:"feature/srs/06-ai-features/3-7-19-recommend-collaborator/plan.md"};function d(n,e,i,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-7-19-recommend-collaborator-uc-106" tabindex="-1">Plan — FR 3.7.19: Recommend Collaborator (<code>UC-106</code>) <a class="header-anchor" href="#plan-—-fr-3-7-19-recommend-collaborator-uc-106" aria-label="Permalink to &quot;Plan — FR 3.7.19: Recommend Collaborator (`UC-106`)&quot;">​</a></h1><h2 id="_1-architectural-scope-touched-repositories" tabindex="-1">1. Architectural Scope &amp; Touched Repositories <a class="header-anchor" href="#_1-architectural-scope-touched-repositories" aria-label="Permalink to &quot;1. Architectural Scope &amp; Touched Repositories&quot;">​</a></h2><p>Implements <strong>FR 3.7.19 — Recommend Collaborator</strong> (<a href="./spec.html">spec.md</a>) for canonical roles <code>Owner, Manager</code> across the BrandHub polyrepo:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Concrete Classes, Endpoints &amp; Modules</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway (<code>brandhub-api-gateway</code>)</strong></td><td style="text-align:left;"><code>InboundSecurityWebFilter.java</code>, <code>JwtAuthFilterGatewayFilterFactory.java</code> (validates JWT, injects <code>X-User-Id</code> / <code>X-Request-Id</code>), <code>RateLimitGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Business Service (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>DirectoryPartnerController.java</code> (<code>POST /api/v1/agencies/{agencyId}/collaborators/recommend</code>), <code>CollaboratorController.java</code> (<code>POST /api/v1/collaborators/agencies/{agencyId}/recommend</code>), <code>ProfileMatchingController.java</code></td></tr><tr><td style="text-align:left;"><strong>AI Service (<code>brandhub-ai-service</code>)</strong></td><td style="text-align:left;"><code>app/api/v1/endpoints/collaborators.py</code> (<code>POST /ai/collaborators/recommend</code>), Brand RAG (<code>VectorStoreService</code>) + LLM multi-criteria scorer</td></tr><tr><td style="text-align:left;"><strong>Data &amp; Persistence Layer</strong></td><td style="text-align:left;">PostgreSQL <code>third_party_collaborators</code> (active candidates <code>is_active = true</code>), <code>client_profiles</code>, <code>ai_credit_reservations</code>; ChromaDB <code>brand_docs_{workspace_id}</code></td></tr><tr><td style="text-align:left;"><strong>Web Application (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>pages/collaborators/page.tsx</code>, <code>pages/campaign-partners/components/CampaignPartnersPanel.tsx</code>, <code>PartnerPicker.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App (<code>brandhub-mobile-app</code>)</strong></td><td style="text-align:left;"><code>src/services/matchingService.ts</code>, <code>src/screens/agency/AgencyCollaboratorsScreen.tsx</code></td></tr><tr><td style="text-align:left;"><strong>i18n Locale Bundles</strong></td><td style="text-align:left;">Web: <code>src/i18n/locales/{vi,en}/collaborators.json</code> (<code>collaborators.recommend.*</code>, <code>collaborators.fitScore.*</code>); Mobile: <code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)</td></tr></tbody></table><h2 id="_2-database-schema-vector-graph-state-contracts" tabindex="-1">2. Database Schema, Vector/Graph State &amp; Contracts <a class="header-anchor" href="#_2-database-schema-vector-graph-state-contracts" aria-label="Permalink to &quot;2. Database Schema, Vector/Graph State &amp; Contracts&quot;">​</a></h2><ol><li><strong>Tenant &amp; Role Boundary Enforcement:</strong><ul><li>Every request resolves caller membership (<code>Owner, Manager</code>) against PostgreSQL <code>agencies</code>, <code>agency_members</code>, and <code>workspace_members</code> before executing any data read, AI dispatch, or mutation.</li><li>Internal <code>business-service -&gt; ai-service</code> HTTP calls authenticate via <code>X-Internal-Api-Key</code> (<code>verify_internal_key</code> in <code>app/core/security.py</code>) and propagate <code>X-Request-Id</code> for distributed tracing.</li></ul></li><li><strong>Persistence &amp; Credit Accounting Invariants:</strong><ul><li>Storage targets: PostgreSQL <code>third_party_collaborators</code> (active candidates <code>is_active = true</code>), <code>client_profiles</code>, <code>ai_credit_reservations</code>; ChromaDB <code>brand_docs_{workspace_id}</code>.</li><li>Where AI inference incurs billable credits (<code>3.7.6</code>, <code>3.7.7</code>, <code>3.7.9</code>, <code>3.7.11</code>, <code>3.7.14</code>, <code>3.7.19</code>), <code>AiCreditGenerationService</code> executes the 3-phase <code>RESERVE -&gt; SETTLE / RELEASE</code> ledger protocol over <code>agency_credit_wallets</code>, <code>workspace_credit_limits</code>, <code>ai_credit_reservations</code>, and <code>credit_operations</code> so upstream timeouts or validation errors release <code>100%</code> of reserved credits.</li><li>Read-only discovery/catalog operations (<code>3.7.1</code>, <code>3.7.2</code>, <code>3.7.3</code>, <code>3.7.8</code>, <code>3.7.10</code>, <code>3.7.12</code>, <code>3.7.15</code>) execute at <code>0</code> AI Credit cost.</li></ul></li></ol><h2 id="_3-end-to-end-execution-data-flow" tabindex="-1">3. End-to-End Execution Data Flow <a class="header-anchor" href="#_3-end-to-end-execution-data-flow" aria-label="Permalink to &quot;3. End-to-End Execution Data Flow&quot;">​</a></h2><ol><li><strong>Client Invocation:</strong> Authenticated actor (<code>Owner, Manager</code>) triggers <code>Recommend Collaborator</code> from <code>brandhub-web</code> or <code>brandhub-mobile-app</code>; client disables duplicate-submit triggers and sends typed request with <code>Authorization: Bearer &lt;token&gt;</code>.</li><li><strong>Gateway &amp; Security Filter:</strong> <code>brandhub-api-gateway</code> verifies JWT signature/expiry, enforces per-route Redis token-bucket rate limits, and forwards identity headers to <code>brandhub-business-service</code>.</li><li><strong>Domain Validation &amp; Authorization:</strong> Controller validates <code>@Valid</code> DTO constraints and delegates to domain service to verify <code>Owner, Manager</code> scope, Agency/Workspace ownership, and entitlement/credit preconditions.</li><li><strong>Core Processing / AI Pipeline Dispatch:</strong> Domain service executes atomic persistence and/or dispatches internal request to <code>brandhub-ai-service</code> with circuit-breaker timeout guards and structured error classification.</li><li><strong>UI Cache &amp; State Reconciliation:</strong> Standardized <code>ApiResponse&lt;T&gt;</code> returns to client; <code>TanStack Query</code> invalidates affected query keys and renders localized (<code>vi</code>/<code>en</code>) feedback in Light/Dark semantic tokens.</li></ol><h2 id="_4-sequential-build-order" tabindex="-1">4. Sequential Build Order <a class="header-anchor" href="#_4-sequential-build-order" aria-label="Permalink to &quot;4. Sequential Build Order&quot;">​</a></h2><ol><li><strong>Step 1 — Schema &amp; Contracts:</strong> Verify PostgreSQL migrations (<code>init-postgres-v2.sql</code> + incremental <code>database/migrations/postgres/*.sql</code>), Pydantic schemas (<code>brandhub-ai-service/app/schemas/</code>), and Java request/response DTOs.</li><li><strong>Step 2 — AI / Domain Service Logic:</strong> Implement and unit-test core Python/Java service methods, circuit breakers, normalization rules, and optimistic/pessimistic concurrency guards.</li><li><strong>Step 3 — REST Controllers &amp; Internal Wiring:</strong> Expose authenticated endpoints in <code>brandhub-business-service</code>, wire <code>RestClient</code> / <code>WebClient</code> internal calls, and map <code>ErrorCode</code> HTTP statuses.</li><li><strong>Step 4 — Web &amp; Mobile UI Integration:</strong> Build/wire React (<code>brandhub-web</code>) and React Native (<code>brandhub-mobile-app</code>) screens, <code>TanStack Query</code> hooks, loading/empty/error states, and keyboard accessibility.</li><li><strong>Step 5 — i18n (<code>vi.json</code> + <code>en.json</code>) &amp; Light/Dark Theme Polish:</strong> Register key-parallel translations in both locales and verify semantic CSS variables / <code>useAppPreferences().palette</code> contrast across Light and Dark modes.</li><li><strong>Step 6 — Automated Verification:</strong> Run JUnit 5, <code>pytest</code>, TypeScript <code>tsc --noEmit</code>, Jest mobile tests, and Playwright UI suites defined in <a href="./test.html">test.md</a>.</li></ol><h2 id="_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" tabindex="-1">5. Localization (<code>vi.json</code> + <code>en.json</code>), Theme Tokens &amp; API Envelope Contract <a class="header-anchor" href="#_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" aria-label="Permalink to &quot;5. Localization (`vi.json` + `en.json`), Theme Tokens &amp; API Envelope Contract&quot;">​</a></h2><ul><li><strong>Standardized <code>ApiResponse&lt;T&gt;</code> Contract:</strong> All JSON endpoints return <code>{ &quot;success&quot;: boolean, &quot;data&quot;: T, &quot;error&quot;: { &quot;code&quot;, &quot;message&quot; } | null, &quot;requestId&quot;: string }</code> with deterministic HTTP status mapping (<code>200/201/204</code> success; <code>400</code> validation; <code>401</code> unauthenticated; <code>402</code> insufficient credit; <code>403</code> role/tenant forbidden; <code>404</code> scoped not found; <code>409</code> version/idempotency conflict; <code>429</code> rate limit; <code>503</code> upstream unavailable).</li><li><strong>Key-Parallel i18n Synchronization:</strong> All UI strings are added simultaneously in <code>vi.json</code> and <code>en.json</code> on <code>brandhub-web</code> and mirrored via <code>tr()</code> (<code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code>) on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Semantic Light &amp; Dark Mode Styling:</strong> Web components use CSS custom properties and Tailwind <code>dark:</code> variants; Mobile screens use <code>useAppPreferences().palette</code> (<code>src/theme/tokens.ts</code>), maintaining WCAG AA contrast across Light and Dark modes.</li></ul><h2 id="_6-engineering-risks-mitigations" tabindex="-1">6. Engineering Risks &amp; Mitigations <a class="header-anchor" href="#_6-engineering-risks-mitigations" aria-label="Permalink to &quot;6. Engineering Risks &amp; Mitigations&quot;">​</a></h2><ul><li><strong>Cross-Tenant Context Leakage:</strong> Never accept <code>workspace_id</code>, <code>agency_id</code>, or candidate arrays blindly from client payloads; always derive or re-query server-side after authorization.</li><li><strong>Upstream LLM / Worker Latency or Outage:</strong> Enforce bounded timeouts, fallback model routing (<code>Groq &lt;-&gt; Gemini</code>), and automatic <code>RELEASE</code> of reserved AI credits on <code>502/503/504</code> failures.</li><li><strong>Stale Concurrent Writes:</strong> Enforce <code>@Version</code> optimistic locking (<code>expectedVersion</code>) and deterministic PostgreSQL row locking on shared directory and campaign records.</li></ul>',15)])])}const m=o(c,[["render",d]]);export{g as __pageData,m as default};
